193	// error; but once the file can be read, all binding gating still runs
194	// against the live store — an unknown version, a draft, a missing artifact
195	// or a wrong hash is reported before any complaint about the file's
196	// contents.
197	func (s *Store) CheckInputFile(name string, version int, hash, path string) (CheckResult, error) {
198		if err := validateCheckRequest(name, version, hash); err != nil {
199			return CheckResult{}, err
