224			t.Fatalf("wire-0 term did not survive reload: %+v", got.Constraints[1].A)
225		}
226		if art, err := s2.CompileCircuit("c", 1); err != nil || art.Hash != want.Hash {
227			t.Fatalf("artifact hash changed across reload: %+v %v", art, err)
228		}
