232	// compatibility boundary: a version whose definition is absent or explicitly
233	// null is still the counts-only state, loads cleanly and later reports a
234	// missing definition when compiled.
235	func TestCountsOnlyAndNullOrMissingDefinitionLoad(t *testing.T) {
236		for _, mode := range []string{"absent", "null"} {
