275	// TestDeletedFieldRejectedEvenWhenEmptyArrayWouldHashSame covers the scenario
276	// from the repair rule: a legal side that was an empty array is saved, the
277	// field is then deleted, and restoring [] would reproduce the identical
278	// artifact hash. The damaged file must still be refused.
279	func TestDeletedFieldRejectedEvenWhenEmptyArrayWouldHashSame(t *testing.T) {
280		const zeroSideDef = `{"modulus":"7","constraints":[
281			{"a":[],"b":[{"wire":1,"coeff":"1"}],"c":[]}]}`
282		dir := filepath.Join(t.TempDir(), "bench")
