297		}
298	
299		env := readGenericEnv(t, dir)
300		con := firstDefinition(t, env)["constraints"].([]any)[0].(map[string]any)
301		delete(con, "a") // "a" was []; restoring [] would keep the same hash
302		bad := writeGenericEnv(t, dir, env)
