	raw = append(raw, '\n')
	if err := os.WriteFile(filepath.Join(dir, dirDataFile), raw, 0o644); err != nil {
		t.Fatal(err)
	}
	return raw
}

// firstDefinition walks to the first circuit's definition object.
func firstDefinition(t *testing.T, env map[string]any) map[string]any {
	t.Helper()
